-- hook_checks: one row per check over toolcall_facts. predicate_sql is a boolean over the relation's columns
-- (true = violation). action: block (deny), warn (allow with additionalContext), deferred (needs the turn).
-- hook_decision is what the PreToolUse hook emits: deny, ask (approval-gated: Alok's click is the yes) or context.
-- Existing hooks in ~/.claude/settings.json PreToolUse, by order: H1 inframe flow gate, H2 Bash duckdb (-init,
-- regexp, OR of LIKE), H3 mcp__dev__ (regexp, OR of LIKE), H4 Bash text readers, H5 mcp__dev__ recursive glob,
-- H6 new TABLE ask, H7 quote chars / variable hand-off / text joining / star count, H8 git show/restore/diff.
-- tools ['@sql'] means every tool that carries SQL: the dev SQL tools, Bash (embedded duckdb) and .sql Write/Edit.
CREATE OR REPLACE VIEW hook_checks AS
WITH primary_checks AS (SELECT unnest([
-- ── Bash: git and gh ──────────────────────────────────────────────────────────────────────────────
{'check_id': 'git_skip_verify', 'rule_id': '01a14828-0966-733b-b2e6-a4137796ec95', 'tools': ['Bash'],
 'predicate_sql': $p$len(list_filter(bash_command_details, d -> d.eff_exe = 'git' AND CASE d.subcommand WHEN 'commit' THEN list_has_any(d.flags, ['--no-verify', '-n']) ELSE list_contains(d.flags, '--no-verify') END)) > 0$p$,
 'message': 'Hooks run on every commit: drop the skip-verification flag and run a slow commit in the background (read_lines(''git commit ... > log 2>&1 & echo $! |'')), then read its log.',
 'action': 'block', 'hook_event': 'PreToolUse', 'hook_decision': 'deny', 'replaces_hooks': []::VARCHAR[]},
{'check_id': 'gh_pr_draft', 'rule_id': '01a14828-0966-7832-9b56-db0612191c3e', 'tools': ['Bash'],
 'predicate_sql': $p$len(list_filter(bash_command_details, d -> d.eff_exe = 'gh' AND d.subcommand = 'pr' AND d.subcommand2 = 'create' AND list_has_any(d.flags, ['--draft', '-d']))) > 0$p$,
 'message': 'Open the PR ready for review: gh pr create without the draft flag (gh pr ready if one was made as a draft).',
 'action': 'block', 'hook_event': 'PreToolUse', 'hook_decision': 'deny', 'replaces_hooks': []::VARCHAR[]},
{'check_id': 'gh_pr_reviewer', 'rule_id': '01a14828-0966-77da-b517-bc42a43afc71', 'tools': ['Bash'],
 'predicate_sql': $p$len(list_filter(bash_command_details, d -> d.eff_exe = 'gh' AND d.subcommand = 'pr' AND d.subcommand2 IN ('create', 'edit') AND list_has_any(d.flags, ['--reviewer', '-r', '--add-reviewer']))) > 0$p$,
 'message': 'Add no reviewers unless Alok asks: drop the reviewer flag; he assigns reviewers himself.',
 'action': 'block', 'hook_event': 'PreToolUse', 'hook_decision': 'deny', 'replaces_hooks': []::VARCHAR[]},
{'check_id': 'gh_pr_create_no_repo', 'rule_id': '01a14828-0966-74a2-ba61-b6e267f35740', 'tools': ['Bash'],
 'predicate_sql': $p$len(list_filter(bash_command_details, d -> d.eff_exe = 'gh' AND d.subcommand = 'pr' AND d.subcommand2 = 'create' AND NOT list_has_any(d.flags, ['--repo', '-R']))) > 0$p$,
 'message': 'Name the target: gh pr create --repo <owner>/<repo>, so a fork never opens against its upstream parent.',
 'action': 'warn', 'hook_event': 'PreToolUse', 'hook_decision': 'context', 'replaces_hooks': []::VARCHAR[]},
{'check_id': 'gh_pr_create_upstream', 'rule_id': '01a14828-0966-70c9-9f83-1785de7dd3dd', 'tools': ['Bash'],
 'predicate_sql': $p$len(list_filter(bash_command_details, d -> d.eff_exe = 'gh' AND d.subcommand = 'pr' AND d.subcommand2 = 'create')) > 0 AND len(list_filter(bash_gh_repos, r -> parse_path(r)[1] NOT IN ('inframe-risk', 'asubbarao'))) > 0$p$,
 'message': 'A PR on someone else''s repo needs Alok''s yes for that PR: show him the repo and the PR body first, and open it from an asubbarao fork.',
 'action': 'block', 'hook_event': 'PreToolUse', 'hook_decision': 'ask', 'replaces_hooks': []::VARCHAR[]},
{'check_id': 'gh_repo_fork', 'rule_id': '01a14828-0966-70c9-9f83-1785de7dd3dd', 'tools': ['Bash'],
 'predicate_sql': $p$list_contains(bash_gh_subcommands, 'repo fork')$p$,
 'message': 'Creating a fork needs Alok''s yes for that repo: name the repo and why first.',
 'action': 'block', 'hook_event': 'PreToolUse', 'hook_decision': 'ask', 'replaces_hooks': []::VARCHAR[]},
{'check_id': 'gh_auth_switch', 'rule_id': '01a14828-0966-7024-9ed8-b9ce5f0e275d', 'tools': ['Bash'],
 'predicate_sql': $p$len(list_filter(bash_command_details, d -> d.eff_exe = 'gh' AND d.subcommand = 'auth' AND d.subcommand2 = 'switch' AND NOT list_contains(d.positionals, 'asubbarao-ifr'))) > 0$p$,
 'message': 'gh stays on asubbarao-ifr: use a per-command GH_TOKEN or SSH for asubbarao, duck_tails or the curl reader for personal-repo reads.',
 'action': 'block', 'hook_event': 'PreToolUse', 'hook_decision': 'deny', 'replaces_hooks': []::VARCHAR[]},
{'check_id': 'gh_pr_merge_no_head_match', 'rule_id': '01a14828-0966-7fb6-a589-b397d0fc3afc', 'tools': ['Bash'],
 'predicate_sql': $p$len(list_filter(bash_command_details, d -> d.eff_exe = 'gh' AND d.subcommand = 'pr' AND d.subcommand2 = 'merge' AND NOT list_contains(d.flags, '--match-head-commit'))) > 0$p$,
 'message': 'Merge only the head Alok approved: gh pr merge --match-head-commit <full 40-char SHA>, after his yes for that PR.',
 'action': 'block', 'hook_event': 'PreToolUse', 'hook_decision': 'deny', 'replaces_hooks': []::VARCHAR[]},
{'check_id': 'gh_pr_merge_needs_yes', 'rule_id': '01a14827-f078-7a0a-95a1-a068ee66aa6f', 'tools': ['Bash'],
 'predicate_sql': $p$len(list_filter(bash_command_details, d -> d.eff_exe = 'gh' AND d.subcommand = 'pr' AND d.subcommand2 = 'merge')) > 0$p$,
 'message': 'Before a merge: "PR #N (short description)" with fix, why, scope, risk, checks and reviewer findings, then Alok''s explicit yes for that PR.',
 'action': 'deferred', 'hook_event': 'PreToolUse + transcript (needs his yes after the last push)', 'hook_decision': 'ask', 'replaces_hooks': []::VARCHAR[]},
{'check_id': 'git_read_cli', 'rule_id': '01a14840-ee81-7898-9c20-368cf0023631', 'tools': ['Bash'],
 'predicate_sql': $p$len(list_filter(bash_command_details, d -> CASE d.eff_exe WHEN 'git' THEN d.subcommand IN ('show', 'restore', 'diff') WHEN 'diff' THEN true ELSE false END)) > 0$p$,
 'message': 'Read a file at a revision with duck_tails: LOAD duck_tails; read_lines(''git://<path>@HEAD''); compare two versions with duck_diff (table_diff_summary). No git show/restore/diff.',
 'action': 'block', 'hook_event': 'PreToolUse', 'hook_decision': 'deny', 'replaces_hooks': ['H8']},
{'check_id': 'git_checkout_paths', 'rule_id': '01a14840-ee81-7898-9c20-368cf0023631', 'tools': ['Bash'],
 'predicate_sql': $p$len(list_filter(bash_command_details, d -> d.eff_exe = 'git' AND d.subcommand = 'checkout' AND list_contains(d.flags, '--'))) > 0$p$,
 'message': 'Restore a file from a revision through duck_tails (read_lines git://<path>@HEAD, COPY back), not git checkout --.',
 'action': 'block', 'hook_event': 'PreToolUse', 'hook_decision': 'deny', 'replaces_hooks': ['H8']},
{'check_id': 'git_log_cli', 'rule_id': '01a14840-ee81-7898-9c20-368cf0023631', 'tools': ['Bash'],
 'predicate_sql': $p$list_contains(bash_git_subcommands, 'log')$p$,
 'message': 'History is a relation: LOAD duck_tails; FROM git_log(''<repo>'') filtered in SQL.',
 'action': 'warn', 'hook_event': 'PreToolUse', 'hook_decision': 'context', 'replaces_hooks': []::VARCHAR[]},
{'check_id': 'git_clone', 'rule_id': '01a14828-0966-7170-9b31-90f13904aff9', 'tools': ['Bash'],
 'predicate_sql': $p$list_contains(bash_git_subcommands, 'clone')$p$,
 'message': 'No second clone: git worktree add for parallel work; read a GitHub repo over HTTPS (read_json on the API tree, read_text on raw files).',
 'action': 'warn', 'hook_event': 'PreToolUse', 'hook_decision': 'context', 'replaces_hooks': []::VARCHAR[]},
{'check_id': 'gh_api_fetch', 'rule_id': '01a14840-ee81-7898-9c20-368cf0023631', 'tools': ['Bash'],
 'predicate_sql': $p$len(list_filter(bash_command_details, d -> d.eff_exe = 'gh' AND d.subcommand = 'api' AND len(list_filter(d.positionals, p -> list_has_any(parse_path(p), ['contents', 'blobs', 'trees', 'raw']))) > 0)) > 0$p$,
 'message': 'Read GitHub content with the curl reader inside SQL (read_json / read_text over a curl pipe), or gh ... --json into read_json; no gh api file fetches.',
 'action': 'warn', 'hook_event': 'PreToolUse', 'hook_decision': 'context', 'replaces_hooks': []::VARCHAR[]},
-- ── Bash: readers, text munging, loops, launchers ─────────────────────────────────────────────────
{'check_id': 'bash_text_readers', 'rule_id': '01a14840-ee81-794c-ae65-8b0436d8afac', 'tools': ['Bash'],
 'predicate_sql': $p$len(list_filter(bash_command_details, d -> CASE d.eff_exe WHEN 'cat' THEN len(d.positionals) > 0 ELSE d.eff_exe IN ('grep', 'egrep', 'rg', 'head', 'tail', 'find', 'less') END)) > 0$p$,
 'message': 'Find files in fs.files / fs.folders and read them with read_lines / read_text (or the Read tool), filtering in SQL; no grep/rg/head/tail/find/less, no cat of a file.',
 'action': 'block', 'hook_event': 'PreToolUse', 'hook_decision': 'deny', 'replaces_hooks': ['H4']},
{'check_id': 'bash_text_munging', 'rule_id': '01a14840-dca3-72bb-90ce-ba54dc54c023', 'tools': ['Bash'],
 'predicate_sql': $p$list_has_any(bash_pipeline_commands, ['sed', 'gsed', 'awk', 'gawk', 'cut', 'tr'])$p$,
 'message': 'Read command output with read_csv / read_json / read_lines over a ''cmd |'' pipe and shape it in SQL (string functions, webbed, netquack); no sed/awk/cut/tr in the pipe.',
 'action': 'block', 'hook_event': 'PreToolUse', 'hook_decision': 'deny', 'replaces_hooks': []::VARCHAR[]},
{'check_id': 'curl_to_dev', 'rule_id': '01a14840-f441-7d8f-8cb6-cbca13215031', 'tools': ['Bash'],
 'predicate_sql': $p$len(list_filter(bash_curl_uris, u -> u.host IN ('localhost', '127.0.0.1', '[::1]') AND u.port IN ('9494', '9495'))) > 0$p$,
 'message': 'Query dev through the dev MCP query / execute tools (self-dispatch from SQL for fan-out); no curl to 9494/9495.',
 'action': 'block', 'hook_event': 'PreToolUse', 'hook_decision': 'deny', 'replaces_hooks': []::VARCHAR[]},
{'check_id': 'duckdb_opens_dev_file', 'rule_id': '01a14840-f441-77d2-b671-faa3e31c03b9', 'tools': ['Bash'],
 'predicate_sql': $p$len(list_filter(bash_duckdb_databases, x -> parse_filename(x) IN ('dev.duckdb', 'dev.duckdb.wal') AND parse_path(x)[-2] = '.duck')) > 0$p$,
 'message': 'Only the quack server opens the dev database: use the dev MCP, or quack_query(''quack:localhost:9494'', ...) from a :memory: client.',
 'action': 'block', 'hook_event': 'PreToolUse', 'hook_decision': 'deny', 'replaces_hooks': []::VARCHAR[]},
{'check_id': 'duckdb_init_flag', 'rule_id': '01a14840-ee81-7b86-aa18-cde8f9cef186', 'tools': ['Bash'],
 'predicate_sql': $p$len(list_filter(bash_command_details, d -> d.eff_exe = 'duckdb' AND list_has_any(d.flags, ['-init', '-no-init']))) > 0
   AND len(list_filter(flatten(list_transform(bash_command_details, d -> coalesce(d.positionals, []))), x -> contains(x, 'LaunchAgents/com.inframe.'))) = 0$p$,
 'message': 'Keep ~/.duckdbrc (resource floor, QueryLog): pass SQL with -c, -f or -cmd, not -init / -no-init.',
 'action': 'block', 'hook_event': 'PreToolUse', 'hook_decision': 'deny', 'replaces_hooks': ['H2']},
{'check_id': 'duckdb_init_flag__plist', 'rule_id': '01a14840-ee81-7b86-aa18-cde8f9cef186', 'tools': ['Bash'],
 'predicate_sql': $p$len(list_filter(bash_command_details, d -> d.eff_exe = 'duckdb' AND list_has_any(d.flags, ['-init', '-no-init']))) > 0
   AND len(list_filter(flatten(list_transform(bash_command_details, d -> coalesce(d.positionals, []))), x -> contains(x, 'LaunchAgents/com.inframe.'))) > 0$p$,
 'message': 'This edits a com.inframe launchd plist, where -init is how the server is meant to start. Approve only if this system change is intended.',
 'action': 'block', 'hook_event': 'PreToolUse', 'hook_decision': 'ask', 'replaces_hooks': ['H2']},
{'check_id': 'duckdb_file_database', 'rule_id': '01a14828-c9e1-786e-aceb-611227cda0fc', 'tools': ['Bash'],
 'predicate_sql': $p$len(list_filter(bash_duckdb_databases, x -> substr(parse_filename(x), length(parse_filename(x, true)) + 1) IN ('.duckdb', '.db', '.ddb'))) > 0$p$,
 'message': 'Answer from the central dev service (dev MCP) or a :memory: client; do not start DuckDB on a database file without a measured reason.',
 'action': 'warn', 'hook_event': 'PreToolUse', 'hook_decision': 'context', 'replaces_hooks': []::VARCHAR[]},
{'check_id': 'bare_python', 'rule_id': '01a14840-ee81-7df9-93dc-6dc65e4f138c', 'tools': ['Bash'],
 'predicate_sql': $p$list_has_any(bash_raw_commands, ['python', 'python3', 'pip', 'pip3', 'virtualenv'])$p$,
 'message': 'Run Python only through uv (uv run, uv add) and only where SQL cannot do the work; no bare python, pip or venv.',
 'action': 'block', 'hook_event': 'PreToolUse', 'hook_decision': 'deny', 'replaces_hooks': []::VARCHAR[]},
{'check_id': 'launchctl', 'rule_id': '01a14828-c9e1-7581-9c4c-23fa2e4f9be0', 'tools': ['Bash'],
 'predicate_sql': $p$len(list_filter(bash_command_details, d -> d.eff_exe = 'launchctl' AND d.subcommand NOT IN ('list', 'print', 'print-disabled', 'blame', 'examine', 'dumpstate', 'help'))) > 0$p$,
 'message': 'launchd and machine-level state change only on Alok''s yes; for dev, use the light-switch skill.',
 'action': 'block', 'hook_event': 'PreToolUse', 'hook_decision': 'ask', 'replaces_hooks': []::VARCHAR[]},
{'check_id': 'pattern_kill', 'rule_id': '01a14840-ee81-78e9-b78b-6dc658ad2953', 'tools': ['Bash'],
 'predicate_sql': $p$list_has_any(bash_commands, ['pkill', 'killall'])$p$,
 'message': 'Stop a process by the PID printed at launch (kill <pid>), or find it with sazgar_processes() in SQL; no pattern kills.',
 'action': 'block', 'hook_event': 'PreToolUse', 'hook_decision': 'deny', 'replaces_hooks': []::VARCHAR[]},
{'check_id': 'detached_launcher', 'rule_id': '01a14840-ee81-7fc3-b026-813eb50d7b73', 'tools': ['Bash'],
 'predicate_sql': $p$len(list_filter(bash_command_details, d -> CASE d.exe WHEN 'nohup' THEN d.eff_exe NOT IN ('sh', 'bash', 'zsh') ELSE d.exe IN ('setsid', 'disown') END)) > 0$p$,
 'message': 'Run background and recurring work as a cronjob row (server/cron.sql) or the run_in_background tool flag; no nohup/setsid/disown launchers.',
 'action': 'block', 'hook_event': 'PreToolUse', 'hook_decision': 'deny', 'replaces_hooks': []::VARCHAR[]},
{'check_id': 'sleep_poll_loop', 'rule_id': '01a14828-c9e1-76cd-94a4-bb76c2532cd5', 'tools': ['Bash'],
 'predicate_sql': $p$bash_uses_sleep AND bash_loop_count > 0$p$,
 'message': 'No polling loops: hand long builds and polls to a Haiku/Luna watcher, or read state as rows once; Monitor for waits.',
 'action': 'block', 'hook_event': 'PreToolUse', 'hook_decision': 'deny', 'replaces_hooks': []::VARCHAR[]},
{'check_id': 'sleep_wait', 'rule_id': '01a14828-c9e1-76cd-94a4-bb76c2532cd5', 'tools': ['Bash'],
 'predicate_sql': $p$bash_uses_sleep AND bash_loop_count = 0$p$,
 'message': 'Do not sleep-wait in the main session: background the command and read its log later, or give the wait to a watcher.',
 'action': 'warn', 'hook_event': 'PreToolUse', 'hook_decision': 'context', 'replaces_hooks': []::VARCHAR[]},
{'check_id': 'shell_loop', 'rule_id': '01a14840-e49f-7553-853a-2c97b1f52026', 'tools': ['Bash'],
 'predicate_sql': $p$bash_loop_count > 0 AND NOT bash_uses_sleep$p$,
 'message': 'Orchestrate without loops: a SELECT builds one statement or command per row and self-dispatch runs them (array_agg(selfdispatch(sql)), CROSS JOIN UNNEST).',
 'action': 'warn', 'hook_event': 'PreToolUse', 'hook_decision': 'context', 'replaces_hooks': []::VARCHAR[]},
{'check_id': 'rm_outside_scratch', 'rule_id': '01a14840-ee81-7704-88ae-5104efb3b04b', 'tools': ['Bash'],
 'predicate_sql': $p$len(list_filter(bash_command_details, d -> d.eff_exe = 'rm' AND len(list_filter(d.positionals, p -> parse_path(p)[1] IN ('/', '~') AND NOT list_has_any(parse_path(p), ['scratchpad', 'tmp', 'private', 'luna_runs']))) > 0)) > 0$p$,
 'message': 'Delete only files you created in your scratch work; anything else needs Alok''s yes with the item, its size and what it is.',
 'action': 'warn', 'hook_event': 'PreToolUse', 'hook_decision': 'context', 'replaces_hooks': []::VARCHAR[]},
{'check_id': 'uninstall_or_terraform', 'rule_id': '01a14840-ee81-7704-88ae-5104efb3b04b', 'tools': ['Bash'],
 'predicate_sql': $p$len(list_filter(bash_command_details, d -> CASE d.eff_exe WHEN 'terraform' THEN d.subcommand IN ('apply', 'destroy', 'import') ELSE d.subcommand = 'uninstall' END)) > 0$p$,
 'message': 'Uninstalls and terraform changes need Alok''s explicit yes; list the item and what it does first.',
 'action': 'block', 'hook_event': 'PreToolUse', 'hook_decision': 'ask', 'replaces_hooks': []::VARCHAR[]},
{'check_id': 'dev_listener_launch', 'rule_id': '01a14840-f441-7bd6-861e-141648b41a77', 'tools': ['Bash'],
 'predicate_sql': $p$list_contains(bash_background_commands, 'duckdb')$p$,
 'message': 'One dev DuckDB on the Mac: query it through the dev MCP; no second, standby or per-agent DuckDB in the background.',
 'action': 'deferred', 'hook_event': 'PreToolUse + task context (an extension test harness in a worktree is not a second dev)', 'hook_decision': 'context', 'replaces_hooks': []::VARCHAR[]},
-- ── Files, agents, Linear, Slack ──────────────────────────────────────────────────────────────────
{'check_id': 'write_shell_script', 'rule_id': '01a14840-e49f-74d0-8cd2-a9f9f57e97f2', 'tools': ['Write'],
 'predicate_sql': $p$tool_name = 'Write' AND file_ext IN ('.sh', '.bash', '.zsh')$p$,
 'message': 'No .sh files in a data path: declare commands as data in a CTE and run them through shellfs inside a .sql file.',
 'action': 'warn', 'hook_event': 'PreToolUse', 'hook_decision': 'context', 'replaces_hooks': []::VARCHAR[]},
{'check_id': 'write_python_helper', 'rule_id': '01a14840-ee81-7c43-8c22-a082a273d37f', 'tools': ['Write'],
 'predicate_sql': $p$tool_name = 'Write' AND file_ext = '.py' AND NOT list_has_all(file_path_parts, ['platform', 'backend'])$p$,
 'message': 'Data work is a .sql file run by DuckDB (shellfs readers, self-dispatch, tera); a thin Python entrypoint that only calls DuckDB is the limit.',
 'action': 'warn', 'hook_event': 'PreToolUse', 'hook_decision': 'context', 'replaces_hooks': []::VARCHAR[]},
{'check_id': 'sql_file_too_long', 'rule_id': '01a14840-ee81-72dc-a559-8e9d1c744378', 'tools': ['Write'],
 'predicate_sql': $p$tool_name = 'Write' AND file_ext = '.sql' AND write_lines > 80$p$,
 'message': 'Keep a job or loader file to 30-80 lines and one concern; split it, or state the reason and line count in the PR.',
 'action': 'warn', 'hook_event': 'PreToolUse', 'hook_decision': 'context', 'replaces_hooks': []::VARCHAR[]},
{'check_id': 'raw_transcript_read', 'rule_id': '01a14840-ee81-79ad-acfd-bc3afaefa733', 'tools': ['Read', 'Write', 'Edit'],
 'predicate_sql': $p$file_ext = '.jsonl' AND list_has_any(file_path_parts, ['.claude', '.codex'])$p$,
 'message': 'Agent history is read with read_conversations / agent.stream / agent_data keyed by session id, never the raw JSONL.',
 'action': 'block', 'hook_event': 'PreToolUse', 'hook_decision': 'deny', 'replaces_hooks': []::VARCHAR[]},
{'check_id': 'team_instructions_edit', 'rule_id': '01a14828-c9e1-779d-8772-ab9d021fc134', 'tools': ['Write', 'Edit'],
 'predicate_sql': $p$tool_name IN ('Write', 'Edit') AND list_contains(file_path_parts, 'inframe') AND list_has_any(list_append(file_path_parts, file_name), ['skills', 'CLAUDE.md', 'AGENTS.md'])$p$,
 'message': 'Team skills and CLAUDE.md change only when Alok asks for that exact change; personal rules go in ~/.claude/CLAUDE.md and memory.',
 'action': 'warn', 'hook_event': 'PreToolUse', 'hook_decision': 'context', 'replaces_hooks': []::VARCHAR[]},
{'check_id': 'agent_without_model', 'rule_id': '01a14840-ee81-7d88-8e68-7b553deb4dcb', 'tools': ['Agent'],
 'predicate_sql': $p$tool_name = 'Agent' AND agent_model IS NULL AND agent_subagent_type IS DISTINCT FROM 'fork'$p$,
 'message': 'Set the model on every dispatch (opus unless Alok names another) and say which model was sent and why.',
 'action': 'block', 'hook_event': 'PreToolUse', 'hook_decision': 'deny', 'replaces_hooks': []::VARCHAR[]},
{'check_id': 'agent_not_opus', 'rule_id': '01a14828-c9e1-76bc-82b8-9c625aa2854c', 'tools': ['Agent'],
 'predicate_sql': $p$tool_name = 'Agent' AND agent_model NOT IN ('opus')$p$,
 'message': 'Dispatch Opus unless Alok named the model in his latest message; Sonnet only for mechanical reads he asked for.',
 'action': 'deferred', 'hook_event': 'PreToolUse + transcript (latest user prompt names the model)', 'hook_decision': 'deny', 'replaces_hooks': []::VARCHAR[]},
{'check_id': 'linear_title_tool_names', 'rule_id': '01a14828-c9e1-7d99-8ed7-1c97ae97bfab', 'tools': ['mcp__linear__save_issue'],
 'predicate_sql': $p$tool_name IN ('mcp__linear__save_issue', 'mcp__linear__save_project', 'mcp__5b54d934-0421-4702-94fb-9066e43667a9__save_issue') AND list_has_any(linear_title_words,['duckdb', 'sql', 'mcp', 'quackapi', 'shellfs', 'parquet', 'json', 'jq', 'regex', 'postgres', 'python'])$p$,
 'message': 'Write the Linear title as a plain outcome sentence with no tool names (run linear-issue-check first).',
 'action': 'warn', 'hook_event': 'PreToolUse', 'hook_decision': 'context', 'replaces_hooks': []::VARCHAR[]},
{'check_id': 'slack_send', 'rule_id': '01a14827-f078-7abf-b24d-6f84075d89d0', 'tools': ['mcp__slack__slack_send_message', 'mcp__slack__slack_schedule_message'],
 'predicate_sql': $p$tool_name IN ('mcp__slack__slack_send_message', 'mcp__slack__slack_schedule_message', 'mcp__dfa81f6c-2e15-4417-8bdf-54a0fe3e18fc__slack_send_message', 'mcp__dfa81f6c-2e15-4417-8bdf-54a0fe3e18fc__slack_schedule_message')$p$,
