 'predicate_sql': $p$tool_name IN ('Edit', 'Write') AND file_ext = '.py' AND list_has_all(file_path_parts, ['platform', 'backend'])$p$,
 'message': 'Backend DuckDB is in-memory and attach-on-demand; durable state lives in Postgres.',
 'action': 'deferred', 'hook_event': 'PreToolUse + Python AST of the new content (sitting_duck python: duckdb.connect with a file path)', 'hook_decision': 'context', 'replaces_hooks': []::VARCHAR[]},
{'check_id': 'large_result_into_context', 'rule_id': '01a14827-f078-7207-841f-e99e3eee8365', 'tools': ['@sql'],
 'predicate_sql': NULL,
 'message': 'Project only the fields or a bounded fragment; never a whole document or blob into context.',
 'action': 'deferred', 'hook_event': 'PostToolUse (result size)', 'hook_decision': 'context', 'replaces_hooks': []::VARCHAR[]},
{'check_id': 'one_keyed_table', 'rule_id': '01a14840-f441-70f1-9360-5ac30cb3b0e9', 'tools': ['@sql'],
 'predicate_sql': NULL,
 'message': 'One keyed table per concept; the branch, file or date is a column, not a table name.',
 'action': 'deferred', 'hook_event': 'SessionEnd catalog scan (duckdb_tables stems)', 'hook_decision': 'context', 'replaces_hooks': []::VARCHAR[]},
{'check_id': 'one_wide_table', 'rule_id': '01a14840-dca3-7cf8-8437-9b2b10cfead5', 'tools': ['@sql'],
 'predicate_sql': NULL,
 'message': 'One wide table or view per data shape; dimension values never become table or column names.',
 'action': 'deferred', 'hook_event': 'SessionEnd catalog scan (duckdb_tables stems)', 'hook_decision': 'context', 'replaces_hooks': []::VARCHAR[]},
{'check_id': 'teammate_machines', 'rule_id': '01a14827-e054-71aa-a062-25b803fc8f28', 'tools': ['Bash'],
 'predicate_sql': NULL,
 'message': 'Make the fix work on Ohad''s and Nando''s machines and show it green in CI before claiming it works.',
 'action': 'deferred', 'hook_event': 'Stop + CI result of the PR', 'hook_decision': 'context', 'replaces_hooks': []::VARCHAR[]},
{'check_id': 'binder_error_is_dispatch', 'rule_id': '01a14840-e49f-71c1-84a3-f649554fef2d', 'tools': ['@sql'],
 'predicate_sql': NULL,
 'message': 'A literal/constant binder error means self-dispatch was skipped: generate one statement per row.',
 'action': 'deferred', 'hook_event': 'PostToolUse (binder error in the result) + Stop', 'hook_decision': 'context', 'replaces_hooks': []::VARCHAR[]},
{'check_id': 'refusal_not_bypassed', 'rule_id': '01a14840-ee81-72e0-b695-a19d7f508d96', 'tools': ['Bash'],
 'predicate_sql': NULL,
 'message': 'When a hook or the binder refuses a call, name it and switch to the house replacement; never reach the same target another way.',
 'action': 'deferred', 'hook_event': 'PostToolUseFailure + next PreToolUse to the same target', 'hook_decision': 'deny', 'replaces_hooks': []::VARCHAR[]}
]::STRUCT(check_id VARCHAR, rule_id VARCHAR, tools VARCHAR[], predicate_sql VARCHAR, message VARCHAR, action VARCHAR,
          hook_event VARCHAR, hook_decision VARCHAR, replaces_hooks VARCHAR[])[], recursive := true)),
-- Rules whose verdict is in the final reply: a Stop hook reads the turn.
stop_rules AS (
  SELECT unnest([
    {'check_id': 'claim_after_run', 'rule_id': '01a14827-f078-7f57-9c51-072df5830f21'},
    {'check_id': 'no_stop_at_blocker', 'rule_id': '01a14827-f078-7093-a9e9-9380df699f29'},
    {'check_id': 'short_status', 'rule_id': '01a14827-f078-7acc-a81f-8efcaa937388'},
    {'check_id': 'docs_before_cannot', 'rule_id': '01a14827-f078-7be1-b9ea-8b73f88d82dd'},
    {'check_id': 'measure_before_stating', 'rule_id': '01a14827-f078-709e-8e25-cdf72f6f3c26'},
    {'check_id': 'open_every_link', 'rule_id': '01a14827-f078-7233-b40e-7056a0b0d5f1'},
    {'check_id': 'remove_named_construct', 'rule_id': '01a14827-f078-7377-95df-cc19ab313618'},
    {'check_id': 'path_in_reply', 'rule_id': '01a14827-f078-7860-a3b8-58c96fab0020'},
    {'check_id': 'run_it_yourself', 'rule_id': '01a14827-f078-7eaa-a42b-a1b52d227fc7'},
    {'check_id': 'light_switch', 'rule_id': '01a14840-f441-7c66-b657-0a23c320439a'},
    {'check_id': 'nothing_lying_around', 'rule_id': '01a14828-0966-7c57-9758-145c6383f207'},
    {'check_id': 'nothing_uncommitted', 'rule_id': '01a14828-0966-7758-9afa-29035c33a1ad'},
    {'check_id': 'finish_every_item', 'rule_id': '01a14828-c9e1-7553-b3d4-d7ae8c2b5c88'},
    {'check_id': 'memory_read_first', 'rule_id': '01a14828-c9e1-70a6-895d-e8bf4c1443bd'},
    {'check_id': 'no_commands_for_alok', 'rule_id': '01a14828-c9e1-7221-948c-457d733dc74b'},
    {'check_id': 'show_output_before_works', 'rule_id': '01a14828-c9e1-7802-8ef2-f2c8cb08ac59'},
    {'check_id': 'no_go_ahead_asks', 'rule_id': '01a14828-c9e1-7d24-92c8-ce8506e58538'},
    {'check_id': 'install_missing_extension', 'rule_id': '01a14840-ee81-73fd-a016-608cd2e74b82'},
    {'check_id': 'read_docs_before_workaround', 'rule_id': '01a14840-ee81-7d5b-a101-873b13b0c573'},
    {'check_id': 'no_manual_steps', 'rule_id': '01a14840-ee81-7ff5-8545-1d7e6301f2cb'}], recursive := true)),
-- Rules enforced by a check written for a sibling rule: same predicate, own rule_id.
alias_rules AS (
  SELECT unnest([
    {'check_id': 'sql_create_macro__dev', 'base_check': 'sql_create_macro', 'rule_id': '01a14840-f441-7619-b47d-819cb9bc22f5'},
    {'check_id': 'sql_create_macro__dispatch', 'base_check': 'sql_create_macro', 'rule_id': '01a14840-e49f-70de-9607-4dbc7f148326'},
    {'check_id': 'sql_create_macro__tooling', 'base_check': 'sql_create_macro', 'rule_id': '01a14840-ee81-711c-b004-cba32508bb4b'},
    {'check_id': 'sql_variable_set__config', 'base_check': 'sql_variable_set', 'rule_id': '01a14840-f441-741c-940d-52218bcbdd6c'},
    {'check_id': 'write_python_helper__dispatch', 'base_check': 'write_python_helper', 'rule_id': '01a14840-e49f-7db7-81e4-b851948d5c4b'},
    {'check_id': 'write_python_helper__sql', 'base_check': 'write_python_helper', 'rule_id': '01a14840-dca3-7d95-ba4d-111b1e7663aa'},
    {'check_id': 'curl_to_dev__mcp', 'base_check': 'curl_to_dev', 'rule_id': '01a14840-ee81-7078-8cf9-aecbfbdbfd7e'},
    {'check_id': 'sql_pattern_functions__tooling', 'base_check': 'sql_pattern_functions', 'rule_id': '01a14840-ee81-7bff-baf1-725ef47b106c'}], recursive := true)),
all_checks AS (
  SELECT * FROM primary_checks
  UNION ALL BY NAME
  SELECT a.check_id, a.rule_id, p.tools, p.predicate_sql, p.message, p.action, p.hook_event, p.hook_decision, []::VARCHAR[] AS replaces_hooks
  FROM alias_rules a JOIN primary_checks p ON p.check_id = a.base_check
  UNION ALL BY NAME
  SELECT s.check_id, s.rule_id, ['(final reply)'] AS tools, NULL AS predicate_sql,
         r.canonical_rule AS message, 'deferred' AS action, 'Stop (reads the final reply and the turn''s tool results)' AS hook_event,
         'block' AS hook_decision, []::VARCHAR[] AS replaces_hooks
  FROM stop_rules s
  JOIN read_parquet('/Users/aloksubbarao/.duck/hook_data/rules_ranked.parquet') AS r USING (rule_id))
SELECT * REPLACE (CASE WHEN tools = ['@sql'] THEN ['mcp__dev__query', 'mcp__dev__execute', 'mcp__dev__query_no_limit',
         'mcp__dev__query_with_limit', 'mcp__dev__sql', 'mcp__dev__self_dispatch', 'Bash', 'Write', 'Edit'] ELSE tools END AS tools)
FROM all_checks;
